SELECT ca.ca_state, SUM(cr.cr_net_loss) AS total_net_loss, COUNT(DISTINCT cs.cs_order_number) AS order_cnt, (SELECT MAX(ws2.ws_net_paid) FROM web_sales ws2) AS max_ws_net_paid_example FROM catalog_sales cs JOIN customer_address ca ON cs.cs_bill_addr_sk = ca.ca_address_sk JOIN catalog_returns cr ON cr.cr_order_number = cs.cs_order_number JOIN web_sales ws ON ws.ws_bill_addr_sk = ca.ca_address_sk WHERE ca.ca_state = 'WV' GROUP BY ca.ca_state HAVING ca.ca_state = 'IN'
